function result = mxa_trivial_sim_fixture()
%MXA_TRIVIAL_SIM_FIXTURE Run a deterministic Simulink model for Engine checks.

tmpRoot = tempname;
mkdir(tmpRoot);

uuid = char(java.util.UUID.randomUUID);
modelName = ['mxa_trivial_sim_' strrep(uuid, '-', '_')];
cleanup = onCleanup(@() cleanup_fixture(modelName, tmpRoot));

new_system(modelName);
set_param( ...
    modelName, ...
    'SolverType', 'Fixed-step', ...
    'Solver', 'FixedStepDiscrete', ...
    'FixedStep', '0.1', ...
    'StopTime', '1.0');

constantPath = [modelName '/constant_value'];
sinkPath = [modelName '/to_workspace'];
add_block( ...
    'simulink/Sources/Constant', ...
    constantPath, ...
    'Value', '2.0', ...
    'SampleTime', '0.1');
add_block( ...
    'simulink/Sinks/To Workspace', ...
    sinkPath, ...
    'VariableName', 'mxa_y', ...
    'SaveFormat', 'Array', ...
    'SampleTime', '0.1');
add_line(modelName, 'constant_value/1', 'to_workspace/1');

simOut = sim(modelName, 'ReturnWorkspaceOutputs', 'on');
y = simOut.get('mxa_y');
sampleCount = size(y, 1);
finalValue = y(end, end);

result = struct( ...
    'stop_time', 1.0, ...
    'sample_count', sampleCount, ...
    'final_value', finalValue);
end

function cleanup_fixture(modelName, tmpRoot)
if bdIsLoaded(modelName)
    bdclose(modelName);
end
if isfolder(tmpRoot)
    rmdir(tmpRoot, 's');
end
end
